def find_pattern_blocks(inp):
    """Find rows that form a repeating pattern block"""
    from collections import Counter
    counts = Counter(sum(inp, []))
    bg = counts.most_common(1)[0][0]

    # Find non-background rows
    non_bg_rows = [i for i in range(len(inp)) if any(c != bg for c in inp[i])]

    if not non_bg_rows:
        return None, None

    # Look for consecutive blocks of 3 rows
    blocks = []
    cur = [non_bg_rows[0]]
    for i in non_bg_rows[1:]:
        if i == cur[-1] + 1:
            cur.append(i)
        else:
            if len(cur) >= 3:
                blocks.append(tuple(cur))
            cur = [i]
    if len(cur) >= 3:
        blocks.append(tuple(cur))

    return blocks, bg

